export default async ({ page, context }) => {
  await page.goto(context.url, { waitUntil: "networkidle2" });
  await page.click('a[href$=".csv"]');
  await new Promise((r) => setTimeout(r, 5000));
};

mutation {
  goto(url: "https://example.com", waitUntil: load) { status }
  paragraph: text(selector: "p") { text }
}

export default async ({ page, context }) => {
  await page.goto(context.url);
  return { data: { title: await page.title() }, type: "application/json" };
};
